function setupProductAutocomplete(){const inp=$('#pname'),box=$('#prod-suggestions');if(!inp||!box)return;const draw=()=>{const term=norm(inp.value),rows=state.products.map((p,i)=>({p,i})).filter(x=>norm(x.p.product_list).includes(term)).slice(0,60);box.innerHTML=rows.map(x=>'<div class="suggestion" data-idx="'+x.i+'"><b>'+esc(x.p.product_list)+'</b><small>'+esc(x.p.sku||'')+' · '+esc(x.p.category||'')+'</small></div>').join('');box.classList.toggle('hidden',!rows.length);box.querySelectorAll('.suggestion').forEach(el=>{el.onclick=()=>selectProduct(state.products[+el.dataset.idx])})};inp.oninput=draw;inp.onfocus=draw;if(!window.__logiProductOutsideBound){window.__logiProductOutsideBound=true;document.addEventListener('click',e=>{if(!e.target.closest('#pname')&&!e.target.closest('#prod-suggestions'))$('#prod-suggestions')?.classList.add('hidden')})}}
