function setupPallets(){if(!$('#pallets').children.length)addPallet();$('#add-pallet').onclick=()=>addPallet();$('#remove-pallet').onclick=()=>{const rows=$('#pallets').children;if(rows.length>1){rows[rows.length-1].remove();calcPallets()}};$('#add-bulk')?.addEventListener('click',()=>{const n=Math.max(1,parseInt($('#bulk-rows').value||'1',10));for(let i=0;i<n;i++)addPallet();calcPallets()});$('#reset-pallets')?.addEventListener('click',()=>{document.querySelectorAll('#pallets>div').forEach(x=>x.remove());addPallet();calcPallets()});$('#cancel-cart-edit')?.addEventListener('click',()=>{state.cartEditIndex=null;updateCartEditIndicator();clearProductWeb(true)})}
function addPallet(){const d=document.createElement('div');d.className='grid g7 pallet-row';d.innerHTML='<span class="row-num"></span><input class="input pal" value="1" type="number" min="0"><input class="input cases" type="number" min="0"><input class="input levels" type="number" min="0"><input class="input ph result" readonly><input class="input pw result" readonly><input class="input ptw result" readonly><input class="input pcs result" readonly>';$('#pallets').appendChild(d);d.querySelectorAll('.pal,.cases,.levels').forEach(x=>x.addEventListener('input',calcPallets));calcPallets();}
function calcPallets(){const h=num($('#pheight').value),hi=num($('#phi').value),w=num($('#pweight').value),tihi=num($('#ptihi').value);let grand=0,totalP=0,lines=[];const mode=$('#maxheight').value||'Altura Máxima: 90"',limit=mode.includes('41"')?41:mode.includes('Personalizada')?(num($('#customheight').value)||999):90;document.querySelectorAll('#pallets>div').forEach((d,i)=>{d.querySelector('.row-num').textContent=i+1;const pal=num(d.querySelector('.pal').value),cs=num(d.querySelector('.cases').value),lev=num(d.querySelector('.levels').value);let hh=0,ww=0;if(lev>0&&hi>0){hh=lev===hi?h:lev<hi?(h/hi*lev)+5:0}if(cs>0&&cs<=tihi)ww=cs*w+42;const tw=ww*pal,tc=pal*cs;grand+=tc;totalP+=pal;d.querySelector('.ph').value=hh?Math.round(hh):'';d.querySelector('.pw').value=ww?Math.round(ww*100)/100:'';d.querySelector('.ptw').value=tw?Math.round(tw*100)/100:'';d.querySelector('.pcs').value=tc?Math.round(tc):'';d.querySelector('.ph').classList.toggle('over-limit',hh>limit);if(pal>0)lines.push(pal+' P , '+tc+' cs (W: '+Math.round(tw*100)/100+' lbs, H: '+Math.round(hh)+'")')});$('#grandtotal').value=grand?Math.round(grand):'';$('#pconfig').value=lines.join(' +\n');$('#pallet-count').textContent=document.querySelectorAll('#pallets>div').length;const ver=$('#pverified')?.value||'',m=/^(\d+)\s*P/i.exec(ver),vp=m?num(m[1]):0;$('#ld_pallets').value=vp>0&&!mode.includes('41"')?vp:(totalP||1);calc();}
function insured(){const q=num($('#pqty').value),p=num($('#pprice').value);$('#pinsured').value=q&&p?'$'+(q*p).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}):''}
