async function saveQuote(){if(!sb){toast('Supabase no está configurado',false);return}const quote=$('#qnum')?.value?.trim(),company=$('#qcompany')?.value?.trim(),address=$('#qaddress')?.value?.trim(),type=$('#qtype')?.value;if(!quote){toast('Falta # QUOTE',false);return}if(!state.cart.length){toast('Agrega al menos un producto al quote',false);return}if(!company||!address||!type||type==='Seleccionar'){toast('Completa Customer Information',false);return}const wasEdit=!!state.edit;if(wasEdit&&!navigator.onLine){toast('La edición requiere conexión. Usa el sistema local sin internet.',false);return}const g={date:$('#qdate').value,email:$('#qemail').value,quote,company,address,type};const iid=state.edit?.quote_instance_id||crypto.randomUUID();const newTable=localType(type)?'local_quotes':'quotes';const oldTable=state.edit?.table||(state.edit&&localType(state.edit.type)?'local_quotes':'quotes');if(wasEdit){const del=await sb.from(oldTable).delete().eq('quote_instance_id',iid);if(del.error){toast('No se pudo preparar la actualización: '+del.error.message,false);return}}const rows=state.cart.map(p=>payloadFromCart(p,g,iid));if(!rows.length){toast('No hay productos para guardar',false);return}if(!navigator.onLine){const pending=JSON.parse(localStorage.getItem('logisuite-pending')||'[]');pending.push({table:newTable,rows});localStorage.setItem('logisuite-pending',JSON.stringify(pending));toast('Sin internet: cotización guardada localmente y pendiente de sincronizar');state.cart=[];state.cartEditIndex=null;state.edit=null;render();return}const ins=await sb.from(newTable).insert(rows);if(ins.error){toast('No se pudo guardar: '+ins.error.message,false);return}toast(wasEdit?'Cotización actualizada correctamente':'Cotización guardada correctamente');state.cart=[];state.cartEditIndex=null;state.edit=null;render()}
